// Explicit Sandbox Scope & Mock Dispatch Validation
const inputData = $input.first()?.json || {};
const scopeTenant = inputData.sandbox_tenant_id || inputData.tenant_id;

// 1. Missing sandbox scope check:
// Execution fails immediately before any database mutation or claim call
if (!scopeTenant || typeof scopeTenant !== 'string' || !scopeTenant.trim()) {
  throw new Error("Missing explicit sandbox tenant scope: A validated sandbox tenant_id (e.g. 'sandbox-services-alpha') is strictly required before claiming test jobs. Never fall back to claiming all tenants.");
}

const cleanTenant = scopeTenant.trim();

// 2. Unauthorized scope check:
// Only sandbox or test tenants are authorized for sandbox testing
if (!cleanTenant.startsWith('sandbox-') && !cleanTenant.startsWith('test-')) {
  throw new Error(`Unauthorized sandbox scope: '${cleanTenant}' is not an authorized sandbox business workspace. Sandbox tests must target 'sandbox-*' or 'test-*' tenants.`);
}

const isMock = inputData.mock !== undefined ? Boolean(inputData.mock) : true;

return [{
  json: {
    ...inputData,
    sandbox_mode: true,
    tenant_id: cleanTenant,
    mock: isMock,
    claim_limit: inputData.limit || 10
  }
}];

// Log zero jobs found
const result = $input.first().json;
console.log('[Services Follow-up] Zero due follow-up jobs claimed. Polling cycle complete.');
return [{
  json: {
    status: 'idle',
    claimed_count: 0,
    message: 'Zero due follow-up jobs claimed.'
  }
}];

// Prepare normalized inspection parameters
const items = $input.all();
const scopeCfg = $('Validate Sandbox Scope & Mock Config').first()?.json || {};

return items.map(entry => {
  const item = entry.json;
  return {
    json: {
      tenant_id: item.tenant_id,
      lead_id: item.lead_id,
      job_id: item.id,
      attempt_count: item.attempt_count || 0,
      max_attempts: item.max_attempts || 2,
      mock: scopeCfg.mock !== undefined ? scopeCfg.mock : true
    }
  };
});

// Preserve tenant_id, lead_id, job_id and validate business inspection response
const items = $input.all();
const prepItems = $('Prepare Lead Inspection').all();

return items.map((entry, idx) => {
  const inspectRes = entry.json || {};
  const prep = prepItems[idx]?.json || {};

  const tenantId = inspectRes.tenant_id || prep.tenant_id;
  const leadId = inspectRes.lead_id || prep.lead_id;
  const jobId = inspectRes.job_id || prep.job_id;

  let permittedPath = inspectRes.permitted_path || inspectRes.action;
  const isValidPath = permittedPath === 'customer_followup' || permittedPath === 'owner_task_escalation' || permittedPath === 'cancel_obsolete';

  const isHttpError = Boolean(inspectRes.error || inspectRes.statusCode >= 400 || inspectRes.success === false);

  if (isHttpError || !isValidPath) {
    permittedPath = 'unknown_failure';
  }

  return {
    json: {
      ...inspectRes,
      tenant_id: tenantId,
      lead_id: leadId,
      job_id: jobId,
      mock: prep.mock !== undefined ? prep.mock : true,
      permitted_path: permittedPath,
      inspection_valid: isValidPath && !isHttpError
    }
  };
});

